package cn.mop.api;
import cn.mop.domain.*;
import cn.mop.domain.calendar.*;
import cn.mop.domain.calendar.WorkingCalendarRepository.*;
import cn.mop.domain.time.IntervalSets.Interval;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import java.util.function.Supplier;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class WorkingCalendarControllerTest {
    static final String ACTOR="55000000-0000-4000-8000-000000000001",TENANT="55000000-0000-4000-8000-000000000011",ID="55000000-0000-4000-8000-000000000021";
    static final Instant START=Instant.parse("2026-10-01T00:00:00Z"),END=START.plusSeconds(86400);
    ObjectMapper mapper=new ObjectMapper();PlatformRepository platform;WorkingCalendarRepository calendars;WorkingCalendarController controller;
    @BeforeEach void setup(){platform=mock(PlatformRepository.class);calendars=mock(WorkingCalendarRepository.class);controller=new WorkingCalendarController(platform,calendars,mapper);when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"padmin",7,true)));}
    MockHttpServletRequest request(String method){var r=new MockHttpServletRequest(method,"/api/v1/working-calendars");r.setUserPrincipal(()->ACTOR);r.getSession().setAttribute("mop.tenant_id",TENANT);r.setAttribute("mop.trace_id","synthetic-trace");r.addHeader("Idempotency-Key","synthetic-request");return r;}
    Access access(){return new Access(ACTOR,TENANT,7,"synthetic-trace");}
    ObjectNode input(){var b=mapper.createObjectNode().put("name","显式草稿").put("coverage_start",START.toString()).put("coverage_end",END.toString()).put("coverage_complete",true).putNull("note");b.putArray("working_windows").addObject().put("start",START.toString()).put("end",END.toString());return b;}
    WorkingCalendarDraft draft(){return new WorkingCalendarDraft("显式草稿",new Interval(START,END),List.of(new Interval(START,END)),true,null);}
    Snapshot snapshot(){return new Snapshot(ID,TENANT,1,draft(),ACTOR,START,START);}
    Map<?,?> data(Object value){return (Map<?,?>)((Map<?,?>)value).get("data");}
    @Test void createUsesTrustedScopeAndGuardThenTransaction(){when(platform.idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any())).thenAnswer(c->{((Runnable)c.getArgument(6)).run();return ((Supplier<?>)c.getArgument(7)).get();});when(calendars.create(access(),draft())).thenReturn(snapshot());var value=data(controller.write(null,input(),request("POST")));assertEquals(ID,value.get("id"));assertEquals(false,value.get("effective"));assertEquals("UNVERIFIED",value.get("customer_confirmation"));var order=inOrder(calendars);order.verify(calendars).authorizeCurrentAccess(access(),null);order.verify(calendars).create(access(),draft());}
    @Test void updateRequiresVersionAndPreservesCalendarGuard(){when(platform.idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any())).thenAnswer(c->{((Runnable)c.getArgument(6)).run();return ((Supplier<?>)c.getArgument(7)).get();});when(calendars.update(access(),ID,1,draft())).thenReturn(snapshot());controller.write(ID,input().put("expected_version",1),request("PATCH"));verify(calendars).authorizeCurrentAccess(access(),ID);verify(calendars).update(access(),ID,1,draft());assertEquals(400,assertThrows(DomainException.class,()->controller.write(ID,input(),request("PATCH"))).status);}
    @Test void otherRolesAndInvalidSessionCannotReadOrPreview(){for(String role:List.of("msp","viewer","tadmin","unknown")){when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,role,7,true)));assertEquals(403,assertThrows(DomainException.class,()->controller.get(ID,request("GET"))).status);}var bad=request("GET");bad.getSession().setAttribute("mop.tenant_id",5);assertEquals(401,assertThrows(DomainException.class,()->controller.get(ID,bad)).status);verifyNoInteractions(calendars);}
    @Test void unknownFieldsAndMissingDeclarationsAreRejected(){for(String key:List.of("tenant_id","actor_id","timezone","effective","customer_confirmation","recurrence","default_hours"))assertEquals(400,assertThrows(DomainException.class,()->controller.write(null,input().put(key,"forged"),request("POST"))).status);var missing=input();missing.remove("coverage_complete");assertEquals(400,assertThrows(DomainException.class,()->controller.write(null,missing,request("POST"))).status);assertEquals(400,assertThrows(DomainException.class,()->controller.write(null,input().putNull("working_windows"),request("POST"))).status);verifyNoInteractions(calendars);}
    @Test void badWindowRangesPrecisionAndUnknownNestedKeysAreRejected(){for(String time:List.of("2026-10-01","2026-10-01T00:00:00.0001Z","2026-13-01T00:00:00Z"))assertEquals(400,assertThrows(DomainException.class,()->controller.write(null,input().put("coverage_start",time),request("POST"))).status);var reversed=input().put("coverage_end",START.toString());assertEquals(400,assertThrows(DomainException.class,()->controller.write(null,reversed,request("POST"))).status);var extra=input();((ObjectNode)extra.get("working_windows").get(0)).put("effective",true);assertEquals(400,assertThrows(DomainException.class,()->controller.write(null,extra,request("POST"))).status);}
    @Test void readPagesDoNotInvokeCommandAndRejectQueryOverrides(){when(calendars.list(access(),16,null,null)).thenReturn(List.of(snapshot()));assertEquals(false,data(controller.list(request("GET"))).get("has_more"));var bad=request("GET");bad.addParameter("tenant_id",TENANT);assertEquals(400,assertThrows(DomainException.class,()->controller.list(bad)).status);var dup=request("GET");dup.addParameter("page_size",new String[]{"10","15"});assertEquals(400,assertThrows(DomainException.class,()->controller.list(dup)).status);verify(platform,never()).idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any());}
    @Test void previewOnlyCalculatesScenarioAndNeverWrites(){when(calendars.get(access(),ID)).thenReturn(snapshot());var b=mapper.createObjectNode().put("expected_version",1).put("start",START.toString()).put("required_seconds",3600);var value=data(controller.preview(ID,b,request("POST")));assertEquals("CALCULATED",value.get("status"));assertEquals(START.plusSeconds(3600),value.get("scenario_deadline"));assertNull(value.get("effective_deadline"));assertEquals(false,value.get("effective"));verify(calendars,never()).create(any(),any());verify(calendars,never()).update(any(),any(),anyLong(),any());verify(platform,never()).idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any());}
    @Test void previewKeepsUnknownValuesAndRejectsStaleVersion(){when(calendars.get(access(),ID)).thenReturn(snapshot());var b=mapper.createObjectNode().put("expected_version",1).putNull("start").putNull("required_seconds");var value=data(controller.preview(ID,b,request("POST")));assertEquals("DURATION_MISSING",value.get("reason"));assertNull(value.get("scenario_deadline"));assertNull(value.get("remaining_duration"));b.put("required_seconds",0);assertEquals("START_MISSING",data(controller.preview(ID,b,request("POST"))).get("reason"));assertEquals(409,assertThrows(DomainException.class,()->controller.preview(ID,b.put("expected_version",2),request("POST"))).status);}
    @Test void strictJsonRejectsDuplicateTrailingTooDeepAndOversizedButAcceptsMaxWindows()throws Exception{for(String value:List.of("{\"name\":\"a\",\"name\":\"b\"}","{} {}","[[[[[1]]]]]"," ".repeat(262145))){var r=request("POST");r.setContent(value.getBytes(StandardCharsets.UTF_8));assertEquals(400,assertThrows(DomainException.class,()->WorkingCalendarController.body(r)).status);}var b=input();var windows=(ArrayNode)b.get("working_windows");for(int i=1;i<1000;i++)windows.add(windows.get(0).deepCopy());var r=request("POST");r.setContent(mapper.writeValueAsBytes(b));assertEquals(b,WorkingCalendarController.body(r));}
    @Test void nestedObjectOrderCanonicalizesButRawValuesStaySignificant(){List<String> hashes=new ArrayList<>();when(platform.idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any())).thenAnswer(c->{hashes.add(c.getArgument(4));return Map.of("receipt",true);});var b=input();controller.write(null,b,request("POST"));((ArrayNode)b.get("working_windows")).removeAll().addObject().put("end",END.toString()).put("start",START.toString());controller.write(null,b,request("POST"));b.put("note","different");controller.write(null,b,request("POST"));assertEquals(hashes.get(0),hashes.get(1));assertNotEquals(hashes.get(0),hashes.get(2));}
    @Test void replayCallbackAuthorizesBeforeCachedResponseWithoutRunningWrite(){when(platform.idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any())).thenAnswer(c->{((Runnable)c.getArgument(6)).run();return Map.of("original",true);});assertEquals(true,data(controller.write(ID,input().put("expected_version",1),request("PATCH"))).get("original"));verify(calendars).authorizeCurrentAccess(access(),ID);verify(calendars,never()).update(any(),any(),anyLong(),any());}
}
